pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Ensure amount is within reasonable bounds
        amount = bound(amount, 1, 1000);

        // Call AdjustBetAmounts to trigger the sequence (though it doesn't affect difficulty)
        c.AdjustBetAmounts(amount);

        // Call AdjustDifficulty with a different value to check the property
        uint256 diffAmount = bound(amount + 1, 1, 1000);

        // Use vm.store to bypass the onlyOwner modifier? No, we can call directly since owner is this contract
        // Actually, owner is address(this) because constructor sets owner = msg.sender, and we deployed from this contract
        c.AdjustDifficulty(diffAmount);

        // The general rule: after AdjustDifficulty(x), currentDifficulty() == x
        // Reference satisfies this, mutant breaks because it stores x+1
        assertTrue(c.currentDifficulty() == diffAmount, "currentDifficulty should equal amount passed to AdjustDifficulty");
    }
}

