pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to a reasonable range
        amount = bound(amount, 0, 1e30);

        // Record the bet limit before the call
        uint256 before = c.currentBetLimit();

        // Call AdjustBetAmounts
        c.AdjustBetAmounts(amount);

        // Record the bet limit after the call
        uint256 after = c.currentBetLimit();

        // The rule: after a call to AdjustBetAmounts, betLimit equals the argument passed
        // In the reference, AdjustBetAmounts sets betLimit = amount, so after should equal amount.
        // The mutant does not change AdjustBetAmounts, so this rule holds for both.
        // But the intended property is that after AdjustBetAmounts(amount), the betLimit is exactly amount.
        // Since the mutant changes wager but not AdjustBetAmounts, both satisfy this.
        // However, we need a rule that the reference satisfies and the mutant breaks.
        // Because the mutant changes require(msg.value == betLimit) to require(msg.value == 0),
        // the wager function will always revert (since msg.value is typically non-zero).
        // The property that distinguishes them is that after AdjustBetAmounts, the wager function
        // correctly sets wagers[msg.sender] to betLimit if called with the correct ether.
        // But reading wagers is public, so we can check it.
        // Let's test: after setting betLimit to amount, if we call wager with amount ether,
        // the reference should set wagers[msg.sender] = amount; the mutant reverts.
        // So we can test that the revert flag is false for reference and true for mutant.
        // To do this generically, we need to include the wager call in the test.
        // Let's restructure:
        // 1. Set betLimit to amount
        c.AdjustBetAmounts(amount);
        // 2. Try to wager with amount ether
        vm.deal(address(this), amount);
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("wager()"));
        // 3. The reference should succeed (success == true), the mutant should fail (success == false)
        // Since the reference succeeds for all inputs, the rule is success == true
        assertTrue(success, "wager should succeed");
    }
}

