// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow issues (use a reasonable range)
        amount = bound(amount, 0, type(uint256).max);
        vm.assume(amount != 0); // optional: avoid zero, but not required

        // Call AdjustBetAmounts to trigger the state difference
        c.AdjustBetAmounts(amount);

        // The general rule: the caller (address(this)) never wagered, so wagers[address(this)] should be 0.
        // This holds in P (where wager() sets wagers), but in M the wager() function never sets wagers,
        // so the condition may become false if any wager() call happened before (but here we haven't called wager).
        // However the difference manifests when wager() is called later; but our rule is that after AdjustBetAmounts
        // the wager balance of the caller remains unchanged (initially 0 because no wager was made).
        // For the reference, if wager() is never called, wagers[address(this)] stays 0.
        // For mutant, wager() also never called, so wagers stays 0 too. But the difference is that if wager() IS called
        // after AdjustBetAmounts, in the reference wagers is set, in mutant not. But the provided difference statement
        // says after a call to AdjustBetAmounts, the value of state variable wager differs: P.wager() != M.wager().
        // That implies we need to call wager() before, or the difference is in the wagers mapping after AdjustBetAmounts
        // when wager() was called previously. So we should call wager() first.
        // Let's rewrite to match the difference description:
    }
    function testFuzz_property_v2(uint256 amount, uint256 betAmount) public {
        amount = bound(amount, 1, 1e18);
        betAmount = bound(betAmount, 1, 1e18);
        // Make the contract open to public
        c.OpenToThePublic();
        // Fund this test contract with ether
        vm.deal(address(this), 1e18);
        // Call wager with some value (equal to betLimit, which is initially 0, so we need to set betLimit first)
        c.AdjustBetAmounts(amount);
        // Now betLimit = amount, so wager with msg.value = amount
        c.wager{value: amount}();
        // Now call AdjustBetAmounts again
        c.AdjustBetAmounts(betAmount);
        // The general rule: after any AdjustBetAmounts call, if we call hasPlayerWagered(address(this)), it should
        // return true because we wagered earlier (reference sets wagers, mutant does not).
        // So the assertion: hasPlayerWagered(address(this)) == true.
        assertTrue(c.hasPlayerWagered(address(this)));
    }
}

