pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player, uint256 amount) public {
        vm.assume(player != address(0));
        // Ensure the contract is open and player can wager
        c.OpenToThePublic();
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.wager{value: 1 ether}();
        bool hadWager = c.hasPlayerWagered(player);

        // Call AdjustBetAmounts which should not change any wager
        c.AdjustBetAmounts(amount);

        // Assert that wager state for player is unchanged
        assertTrue(c.hasPlayerWagered(player) == hadWager);
    }
}

