pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(address player, uint256 betLimit) public {
        vm.assume(player != address(0) && player != address(this));
        betLimit = bound(betLimit, 1, 1e18);

        // Open the contract to the public
        c.OpenToThePublic();

        // Fund the player and make them wager
        vm.deal(player, betLimit);
        vm.prank(player);
        c.wager{value: betLimit}();

        // Call AdjustBetAmounts to change the bet limit
        c.AdjustBetAmounts(betLimit * 2);

        // Now play should revert because block.number == blockNumber (same block)
        // In reference: blockNumber = timestamps[player] = block.number; condition fails => revert
        // In mutant: blockNumber = block.number; condition fails => revert (both same behave the same here)
        // Actually both revert here. Need different scenario.
        // Let's test: player wagered in previous block, then AdjustBetAmounts, then play
        // But to create a block difference we need to mine a block
        vm.roll(block.number + 1);

        // Now player plays
        vm.prank(player);
        (bool success, ) = address(c).call(abi.encodeWithSignature("play()"));
        // Reference: blockNumber = timestamps[player] = old block; block.number > blockNumber => proceeds
        // Mutant: blockNumber = block.number; block.number < block.number is false => revert
        // So success is true for reference, false for mutant
        assertTrue(success == true);
    }
}

